// ─────────────────────────────────────────────────────────────────
// CONFIGURE: Replace with your webinar date/time in ISO 8601 UTC.
// Example: '2025-08-15T14:30:00Z'  →  Aug 15 2025, 8:00 PM IST
// ─────────────────────────────────────────────────────────────────
const WEBINAR_TIME_UTC = new Date('PUT_WEBINAR_ISO_DATETIME_UTC_HERE');

// ±30 minute window: the workflow runs hourly, so any run within
// 30 min of the target reminder time will trigger the email.
const BUFFER_MS = 30 * 60 * 1000;
const TARGET_24H_MS = 24 * 60 * 60 * 1000;
const TARGET_1H_MS = 1 * 60 * 60 * 1000;

const now = new Date();
const msUntilWebinar = WEBINAR_TIME_UTC.getTime() - now.getTime();

// Webinar is in the past – nothing to send
if (msUntilWebinar <= 0) return [];

const result = [];

for (const item of $input.all()) {
  const row = item.json;

  // Skip incomplete rows
  if (!row['Work Email'] || !row['Participant ID']) continue;

  // Check 24-hour reminder
  if (
    row['Reminder1_Sent'] !== 'TRUE' &&
    Math.abs(msUntilWebinar - TARGET_24H_MS) <= BUFFER_MS
  ) {
    result.push({ json: { ...row, reminderType: '24h', reminderLabel: '24 hours' } });
    continue; // One reminder per run per registrant
  }

  // Check 1-hour reminder
  if (
    row['Reminder2_Sent'] !== 'TRUE' &&
    Math.abs(msUntilWebinar - TARGET_1H_MS) <= BUFFER_MS
  ) {
    result.push({ json: { ...row, reminderType: '1h', reminderLabel: '1 hour' } });
  }
}

// Empty array → no downstream nodes run (no-op for this hour)
return result;
